from pathlib import Path
p=Path('places.html')
s=p.read_text()
css='''\n    .service-app{margin-top:18px}.service-app-intro{padding:16px;border:1px solid #bfd5da;border-radius:15px;background:#fff}.service-app-intro h2{margin:0 0 7px;font-size:1rem}.service-app-intro .guide-values{margin-top:0}.service-app-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:12px}.service-app-card{display:block;min-height:108px;padding:15px;border:1px solid #c8dce0;border-radius:15px;background:#fff;color:var(--ink);text-decoration:none;box-shadow:0 6px 16px rgba(18,59,75,.055)}.service-app-card strong{display:block;font-size:.92rem;line-height:1.2}.service-app-card span{display:block;margin-top:6px;color:#647d86;font-size:.72rem;line-height:1.35;font-weight:700}.service-app-card.internal{border-color:#93c4cc;background:#f2fafb}.service-app-section{scroll-margin-top:12px;margin-top:20px}.service-app-section>h2{margin:0 0 10px;font-size:1rem}.contact-scope{margin:0 0 8px;color:#6c838b;font-size:.7rem;font-weight:800}.internal-contact-scope{margin:0 0 10px;color:#37626d;font-size:.72rem;font-weight:800}@media(max-width:520px){.service-app-grid{grid-template-columns:1fr 1fr}.service-app-card{min-height:96px;padding:13px}}\n'''
if '.service-app{' not in s:s=s.replace('</style>',css+'</style>',1)
start=s.index('function serviceGuideData(p){')
end=s.index('\nfunction completionRowHtml',start)
new=r'''function serviceGuideData(p){return{routeMarkup:routesHtml(p),nearMarkup:relationsHtml(p),arrival:tagValuesFor(p,['arrival:','arrivee:','repere_arrivee:']),inside:tagValuesFor(p,['inside:','dans_service:']),landmarks:tagValuesFor(p,['landmark:','repere:']),access:tagValuesFor(p,['accessibility:','accessibilite:']),purpose:servicePurposeValues(p),publicPhone:publicContactValues(p,['public_phone:','phone_public:','tel_public:']),publicEmail:publicContactValues(p,['public_email:','email_public:']),publicUrl:publicContactValues(p,['public_url:','website:','site_web:'])}}
function publicContactsHtml(g){const contacts=[];g.publicPhone.forEach(v=>contacts.push(publicContactItemHtml('Téléphone public',v,'phone')));g.publicEmail.forEach(v=>contacts.push(publicContactItemHtml('E-mail public',v,'email')));g.publicUrl.forEach(v=>contacts.push(publicContactItemHtml('Site officiel',v,'url')));return contacts.length?`<p class="contact-scope">Coordonnées destinées aux personnes extérieures au service.</p><div class="public-contact-grid">${contacts.join('')}</div>`:guidePlaceholder('Contact public à compléter.')}
function appCard(href,title,sub,internal=false){return `<a class="service-app-card${internal?' internal':''}" href="${href}"><strong>${esc(title)}</strong><span>${esc(sub)}</span></a>`}
function serviceGuideHtml(p){const g=serviceGuideData(p),intro=g.purpose.length?valuesHtml(g.purpose):guidePlaceholder('Présentation du service à compléter.'),arrival=g.arrival.length?valuesHtml(g.arrival):'',inside=g.inside.length?valuesHtml(g.inside):'',landmarks=g.landmarks.length?valuesHtml(g.landmarks):'',access=g.access.length?valuesHtml(g.access):'';return `<section class="service-app"><div class="service-app-intro"><h2>Le service</h2>${intro}</div><div class="service-app-grid">${appCard('#service-route','Comment y aller','Trajet, étage et repères')}${appCard('#service-near','À proximité','Services et destinations proches')}${appCard('#service-inside','Dans le service','Organisation et repères sur place')}${appCard('#service-contact','Contact','Coordonnées publiques')}${appCard('#service-access','Accessibilité','Accès et parcours adaptés')}${appCard('#service-arrival','Reconnaître l’arrivée','Savoir que tu es au bon endroit')}</div><section class="service-app-section" id="service-route"><h2>Comment y aller</h2>${g.routeMarkup||guidePlaceholder()}</section><section class="service-app-section" id="service-near"><h2>À proximité</h2>${g.nearMarkup||guidePlaceholder()}</section><section class="service-app-section" id="service-arrival"><h2>Reconnaître l’arrivée</h2>${arrival||guidePlaceholder()}</section><section class="service-app-section" id="service-inside"><h2>Dans le service</h2>${inside||guidePlaceholder()}${landmarks?`<div class="guide-block"><h2>Repères et équipements utiles</h2>${landmarks}</div>`:''}</section><section class="service-app-section" id="service-contact"><h2>Contact</h2>${publicContactsHtml(g)}</section><section class="service-app-section" id="service-access"><h2>Accessibilité</h2>${access||guidePlaceholder()}</section></section>`}
'''
s=s[:start]+new+s[end:]
# replace internal function only
start=s.index('function internalServiceHtml(p){')
end=s.index('\n\nfunction renderPlace',start)
new2=r'''function internalServiceHtml(p){if(!isInternalAccess())return'';const g=serviceGuideData(p),transport=tagValuesFor(p,['transport:','patient_transport:']),staffElev=tagValuesFor(p,['staff_elevator:','elevator_staff:','ascenseur_pro:']),contacts=tagValuesFor(p,['contact:','phone:','tel:','telephone:','internal_email:','email_internal:']),particular=tagValuesFor(p,['internal:','particularity:','particularite:']),warnings=tagValuesFor(p,['warning:','vigilance:']),shortcuts=tagValuesFor(p,['shortcut:','raccourci:','liaison_pro:']),care=tagValuesFor(p,['care:','prise_en_charge:']),temporary=tagValuesFor(p,['temporary:','temporaire:']),notes=tagValuesFor(p,['internal_note:','note_terrain:']);const publicContactDone=g.publicPhone.length>0||g.publicEmail.length>0||g.publicUrl.length>0;const tracker=[['À quoi sert ce service',g.purpose.length>0],['Contact public',publicContactDone],['Comment y aller',!!g.routeMarkup],['À proximité',!!g.nearMarkup],['Reconnaître l’arrivée',g.arrival.length>0],['Dans le service',g.inside.length>0],['Repères / équipements',g.landmarks.length>0],['Accessibilité',g.access.length>0],['Transport patient',transport.length>0],['Ascenseurs professionnels',staffElev.length>0],['Contacts internes',contacts.length>0],['Particularités du service',particular.length>0],['Points de vigilance',warnings.length>0],['Raccourcis / liaisons',shortcuts.length>0],['Prise en charge particulière',care.length>0],['Informations temporaires',temporary.length>0],['Notes terrain STIP',notes.length>0]];return `<div class="internal-divider"><span>Informations internes STIP</span></div><section class="internal-zone"><p>Réservé aux professionnels connectés. Aucun contact interne n’est affiché en accès visiteur.</p><div class="service-app-grid">${appCard('#internal-transport','Transport patient','Prise en charge et dépose',true)}${appCard('#internal-access','Accès professionnels','Ascenseurs et circuits métier',true)}${appCard('#internal-contact','Contacts internes','Postes et coordonnées professionnelles',true)}${appCard('#internal-vigilance','Points de vigilance','Particularités et informations terrain',true)}</div><div class="internal-subtitle">Avancement de la fiche</div><div class="completion-grid">${tracker.map(x=>completionRowHtml(x[0],x[1])).join('')}</div><div class="internal-subtitle">Informations métier</div><div class="internal-cards"><div id="internal-transport">${internalCardHtml('Transport patient',transport)}${internalCardHtml('Prise en charge particulière',care)}</div><div id="internal-access">${internalCardHtml('Ascenseurs professionnels',staffElev)}${internalCardHtml('Raccourcis et liaisons professionnelles',shortcuts)}</div><div id="internal-contact"><p class="internal-contact-scope">Contacts strictement internes : postes, numéros directs et e-mails professionnels. Ils ne sont jamais repris dans le contact public.</p>${internalCardHtml('Contacts internes',contacts)}</div><div id="internal-vigilance">${internalCardHtml('Particularités du service',particular)}${internalCardHtml('Points de vigilance',warnings)}${internalCardHtml('Informations temporaires',temporary)}${internalCardHtml('Notes terrain STIP',notes)}</div></div></section>`}'''
s=s[:start]+new2+s[end:]
# remove legacy rdv wording if any remains in service guide tracker/content
s=s.replace('Contact public / rendez-vous','Contact public').replace('Coordonnées publiques et rendez-vous à compléter.','Contact public à compléter.').replace('Venir ici / prendre rendez-vous','Contact')
s='\n'.join(x.rstrip() for x in s.splitlines())+'\n'
p.write_text(s)
